parameters.jsCode:
const f = $input.first().json;

const niche = String(f['Industry or Niche'] || '').trim();
const location = String(f['Location'] || '').trim();
const keywords = String(f['Extra Keywords'] || '').trim();
const icp = String(f['Ideal Customer Profile'] || '').trim();

if (!niche || !location) {
  throw new Error('Industry or Niche and Location are both required.');
}

const code = (value, fallback) => {
  const s = String(value || '').trim().toLowerCase();
  return /^[a-z]{2}$/.test(s) ? s : fallback;
};

const region = code(f['Search Region'], 'us');
const language = code(f['Search Language'], 'en');

const minScore = Math.min(100, Math.max(0, Number(f['Minimum Lead Score']) || 60));
const maxCompanies = Math.min(25, Math.max(1, Number(f['Max Companies To Process']) || 5));

const keywordVariations = Math.min(10, Math.max(1, Number(f['Keyword Variations']) || 5));

const query = [niche, location, keywords].filter(Boolean).join(' ');

return [
  {
    json: {
      query, niche, location, keywords, icp,
      region, language, minScore, maxCompanies, keywordVariations,
    },
  },
];

const cfg = $('Build Search Query').first().json;

const source = [];
const emptyKeys = [];

for (const item of $input.all()) {
  const data = item.json.data || {};
  const normalized = Array.isArray(data.results) ? data.results : [];
  const organic = Array.isArray(data.organic) ? data.organic : [];

  if (normalized.length) {
    for (const r of normalized) {
      source.push({
        url: r.url,
        title: r.title || '',
        snippet: r.description || '',
        relevance: r.relevance || '',
      });
    }
  } else if (organic.length) {
    for (const r of organic) {
      source.push({
        url: r.link,
        title: r.title || '',
        snippet: r.description || '',
        relevance: '',
      });
    }
  } else {
    emptyKeys.push(Object.keys(data).join(', ') || '(no data key)');
  }
}

if (source.length === 0) {
  throw new Error(
    `All ${$input.all().length} MrScraper SERP responses were empty. Keys seen under data: ` +
      emptyKeys.join(' | ') +
      '. Try a different niche or location.'
  );
}

const SKIP_HOSTS = [
  'facebook.com', 'instagram.com', 'linkedin.com', 'twitter.com', 'x.com',
  'tiktok.com', 'youtube.com', 'pinterest.', 'reddit.com', 'medium.com',
  'wikipedia.org', 'amazon.', 'ebay.', 'tokopedia.', 'shopee.',
  'indeed.com', 'glassdoor.', 'crunchbase.com', 'yellowpages.',
  'clutch.co', 'g2.com', 'goodfirms.co', 'trustpilot.', 'scribd.com',
  'slideshare.', 'freightnet.com',
];

const looksLikeListicle = (title) => {
  const t = String(title || '').toLowerCase();
  if (/\btop\s+\d+\b/.test(t)) return true;
  if (/\blist of\b|\bdirectory\b|\brankings?\b/.test(t)) return true;
  const plural = /\b(companies|providers|firms|agencies|services|forwarders|clinics|vendors)\b/.test(t);
  return plural && /\btop\b|\bbest\b|\breviews?\b/.test(t);
};

const hostOf = (url) => {
  const m = /^https?:\/\/([^/?#]+)/i.exec(String(url || ''));
  if (!m) return '';
  return m[1].toLowerCase().replace(/^www\./, '').replace(/:\d+$/, '');
};

const seen = new Set();
const out = [];

for (const item of source) {
  const host = hostOf(item.url);
  if (!host) continue;
  if (SKIP_HOSTS.some((s) => host.includes(s))) continue;
  if (looksLikeListicle(item.title)) continue;
  if (seen.has(host)) continue;
  seen.add(host);

  out.push({
    json: {
      url: item.url,
      domain: host,
      serpTitle: item.title,
      serpSnippet: item.snippet,
      serpRelevance: item.relevance,
    },
  });

  if (out.length >= cfg.maxCompanies) break;
}

if (out.length === 0) {
  throw new Error(
    `All ${source.length} search results across ${$input.all().length} keywords were ` +
      'directories, listicles or social profiles. Try a narrower niche or a different location.'
  );
}

return out;

const src = $('Loop Over Companies').item.json;
const raw = $input.first().json;

// The agent wraps its payload in a container that varies with the scrape mode.
function unwrap(value, depth) {
  if (!value || typeof value !== 'object' || depth > 4) return null;
  for (const key of ['data', 'result', 'output', 'response', 'extracted', 'json']) {
    const inner = value[key];
    if (inner && typeof inner === 'object') {
      return unwrap(inner, depth + 1) || inner;
    }
  }
  return null;
}

const d = unwrap(raw, 0) || raw;

const str = (v) => {
  if (typeof v === 'string') return v.trim();
  if (Array.isArray(v)) return v.filter((x) => typeof x === 'string').join(', ');
  return '';
};

const first = (...vals) => {
  for (const v of vals) {
    const s = str(v);
    if (s) return s;
  }
  return '';
};

return [{
  json: {
    companyName: first(d.companyName, d.company_name, d.name) || src.serpTitle || src.domain,
    website: src.url,
    domain: src.domain,
    description: first(d.description, d.businessDescription, d.about) || src.serpSnippet,
    services: first(d.services, d.products, d.offerings),
    email: first(d.email, d.emails, d.contactEmail),
    phone: first(d.phone, d.phones, d.phoneNumber, d.telephone),
    socialMedia: first(d.socialMedia, d.social, d.socialLinks),
    location: first(d.location, d.address, d.city),
    scrapedAt: new Date().toISOString(),
  },
}];

parameters.text:
=You are a B2B sales research analyst. Score how well the company below matches the Ideal Customer Profile, then write a personalized opening line for a cold outreach email.

## Ideal Customer Profile
{{ $('Build Search Query').first().json.icp }}

## Target segment
Industry / niche: {{ $('Build Search Query').first().json.niche }}
Location: {{ $('Build Search Query').first().json.location }}

## Company to evaluate
Name: {{ $json.companyName }}
Website: {{ $json.website }}
Location: {{ $json.location }}
Description: {{ $json.description }}
Services / products: {{ $json.services }}

## Scoring rules
- leadScore runs 0-100.
- Start from segment fit. A company that genuinely operates in the target industry AND the target location starts around 65. Raise it for specific evidence that it matches the ICP or needs what is being sold; lower it for weak or contradictory evidence.
- A company outside the target industry or the target location cannot score above 35, however successful it looks.
- Judge only on the evidence above. If the page gave you little to work with, say so in scoreReason rather than inventing detail — do not invent a penalty either.

## Icebreaker rules
- One or two sentences, under 40 words.
- Reference something concrete and specific to THIS company, taken from its description or services.
- No flattery, no "I came across your website", no generic praise.
- It must read like a line written for one real company, not a template with the name swapped in.

parameters.inputSchema:
{
  "type": "object",
  "required": ["leadScore", "scoreReason", "buyingSignals", "icebreaker"],
  "properties": {
    "leadScore": {
      "type": "number",
      "description": "How well this company matches the ICP, 0-100"
    },
    "scoreReason": {
      "type": "string",
      "description": "One sentence explaining the score"
    },
    "buyingSignals": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Concrete signals that this company needs the product"
    },
    "icebreaker": {
      "type": "string",
      "description": "Personalized opening line, under 40 words"
    }
  }
}

parameters.jsCode:
const cfg = $('Build Search Query').first().json;
const c = $('Normalize Company Data').item.json;
const ai = $input.first().json;
const out = ai.output || ai;

const signals = Array.isArray(out.buyingSignals)
  ? out.buyingSignals.join('; ')
  : String(out.buyingSignals || '');

const score = Number(out.leadScore) || 0;
const email = c.email || '';
const phone = c.phone || '';
const phoneCell = phone ? "'" + phone : '';

const qualified = score >= cfg.minScore && Boolean(email || phone);

return [{
  json: {
    Company: c.companyName,
    Website: c.website,
    Description: c.description,
    Services: c.services,
    Email: email,
    Phone: phoneCell,
    'Social Media': c.socialMedia,
    Location: c.location,
    'Lead Score': score,
    'Score Reason': String(out.scoreReason || ''),
    'Buying Signals': signals,
    Icebreaker: String(out.icebreaker || ''),
    Status: qualified ? 'Qualified' : 'Disqualified',
    'Scraped At': c.scrapedAt,
  },
}];

const cfg = $('Build Search Query').first().json;
const all = $input.all().map((i) => i.json);

const qualified = all.filter((l) => l.Status === 'Qualified');

qualified.sort((a, b) => (b['Lead Score'] || 0) - (a['Lead Score'] || 0));

const lines = qualified.slice(0, 10).map((l, i) =>
  `${i + 1}. ${l.Company} — score ${l['Lead Score']} — ${l.Email || String(l.Phone || '').replace(/^'/, '') || 'no direct contact'}\n   ${l.Icebreaker}`
);

return [{
  json: {
    query: cfg.query,
    minScore: cfg.minScore,
    companiesProcessed: all.length,
    qualifiedLeads: qualified.length,
    subject: `${qualified.length} new qualified leads — ${cfg.niche} in ${cfg.location}`,
    body: lines.length
      ? `Search: ${cfg.query}\nScore threshold: ${cfg.minScore}\nCompanies processed: ${all.length}\n\n${lines.join('\n\n')}`
      : `Search: ${cfg.query}\nCompanies processed: ${all.length}\n\nNone cleared the score threshold of ${cfg.minScore} on this run.`,
  },
}];

parameters.text:
=You are a B2B lead researcher. Write alternative Google search queries that surface the websites of individual companies matching the profile below.

## Target segment
Industry / niche: {{ $json.niche }}
Location: {{ $json.location }}
Extra keywords: {{ $json.keywords }}

## Ideal Customer Profile
{{ $json.icp }}

## Query already being searched
{{ $json.query }}

## Rules
- Return exactly {{ $json.keywordVariations - 1 }} queries.
- Every query must differ from the query above and from each other. Vary the angle, not just the word order: industry synonyms, the local-language term for the same business, adjacent service names, and the phrases these companies use to describe themselves on their own sites.
- Keep the location in every query, written in the same language as the rest of that query.
- Aim at company websites, not articles about them. Never write "top 10", "best", "list of", "vs", "reviews", or directory phrasing.
- Plain search phrases only - no quotes, no boolean operators, no site: filters.

parameters.inputSchema:
{
  "type": "object",
  "required": [
    "queries"
  ],
  "properties": {
    "queries": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Alternative Google search queries, one plain phrase per entry"
    }
  }
}

parameters.jsCode:
const cfg = $('Build Search Query').first().json;
const ai = $input.first().json;
const out = ai.output || ai;

const queries = [cfg.query];
const seen = new Set([cfg.query.toLowerCase()]);

for (const raw of Array.isArray(out.queries) ? out.queries : []) {
  const q = String(raw || '').replace(/["']/g, '').replace(/\s+/g, ' ').trim();
  if (!q) continue;
  const key = q.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  queries.push(q);
  if (queries.length >= cfg.keywordVariations) break;
}

return queries.map((query) => ({
  json: { query, region: cfg.region, language: cfg.language },
}));
